import fs from 'node:fs';
const source = new URL('../styles/design-system.css', import.meta.url);
const destination = new URL('../workers/community/src/design-system.generated.ts', import.meta.url);
const output =
  '// Generated by scripts/sync-design.mjs from styles/design-system.css.\nexport const designSystem = ' +
  JSON.stringify(fs.readFileSync(source, 'utf8').replace(/\r\n/g, '\n')) +
  ';\n';
if (process.argv.includes('--check')) {
  if (
    !fs.existsSync(destination) ||
    fs.readFileSync(destination, 'utf8').replace(/\r\n/g, '\n') !== output
  )
    throw Error('Shared design changed: run npm run sync:design.');
} else fs.writeFileSync(destination, output);
